<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require_business_portal_access();
require dirname(__DIR__,2).'/app/BusinessAccountPortalService.php';
$pdo=db();$service=new BusinessAccountPortalService($pdo);$error='';$destinationId=max(0,(int)($_POST['destination_id']??$_GET['destination_id']??0));
if(($_GET['search']??'')==='1'){
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    try{
        $category=(string)($_GET['category']??'');$term=trim((string)($_GET['q']??''));
        if($category==='__categories__'){$results=$service->registrationCategories($destinationId);}
        else{$results=$service->searchRegistrationBusinesses($destinationId,$category,$term);}
        echo json_encode(['results'=>$results],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
    }catch(Throwable){http_response_code(400);echo '{"results":[]}';}exit;
}
$destinations=$service->registrationDestinations();$categories=$destinationId?$service->registrationCategories($destinationId):[];
try{
 if(!business_portal_available())throw new RuntimeException('El registro de cuentas empresariales todavía no está habilitado.');
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();if(!throttle('business_account_register_form',12,900))throw new RuntimeException('Demasiados intentos. Inténtalo más tarde.');
  if(($_POST['password']??'')!==($_POST['password_confirm']??''))throw new RuntimeException('Las contraseñas no coinciden.');
  $application=['application_type'=>(string)($_POST['application_type']??''),'business_id'=>(string)($_POST['business_id']??''),'business_name'=>(string)($_POST['business_name']??''),'destination_id'=>(string)($_POST['destination_id']??''),'category_code'=>(string)($_POST['category_code']??''),'relationship_code'=>(string)($_POST['relationship_code']??''),'phone'=>(string)($_POST['phone']??''),'message'=>(string)($_POST['message']??''),'consent'=>(string)($_POST['consent']??'')];
  $accountId=$service->register((string)($_POST['display_name']??''),(string)($_POST['email']??''),(string)($_POST['password']??''),$application);
  session_regenerate_id(true);$_SESSION['business_account_id']=$accountId;$_SESSION['business_last_seen']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));
  header('Location: /v1/negocios/portal/?solicitud=recibida',true,303);exit;
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Ya existe una cuenta con ese correo o no fue posible guardar la solicitud.':$e->getMessage();http_response_code(400);}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Registrar negocio | Explorando Lugares</title><link rel="stylesheet" href="/v1/assets/style.css?v=business-portal-3"><link rel="icon" href="/v1/assets/favicon.svg" type="image/svg+xml"></head><body><main class="wrap admin-page account-portal"><a class="brand" href="/v1/index.html"><img class="brand-logo" src="/v1/assets/logo.svg" alt="" width="64" height="64"><span>Explorando<b>Lugares</b></span></a><p><a href="/v1/negocios-locales/">← Negocios locales</a></p><section class="account-portal-card account-registration-card"><p class="eyebrow">Espacio para negocios</p><h1>Vincula tu negocio a una cuenta</h1><p>Primero buscamos si ya tenemos el negocio, incluso si todavía no aparece publicado. Si no está en nuestros registros, puedes solicitar que lo revisemos. La cuenta y la solicitud no publican información ni confirman representación.</p><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><form method="post" class="registration-form" id="business-registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><fieldset><legend>1. Busca el negocio</legend><div class="destination-form-grid"><label>Destino<select name="destination_id" id="registration-destination" required><option value="">Selecciona un destino</option><?php foreach($destinations as $item):?><option value="<?=esc($item['id'])?>" <?=$destinationId===(int)$item['id']?'selected':''?>><?=esc($item['display_name'])?></option><?php endforeach ?></select></label><label>Categoría<select name="category_code" id="registration-category" required <?=$categories?'':'disabled'?>><option value="">Selecciona una categoría</option><?php foreach($categories as $item):?><option value="<?=esc($item['code'])?>" <?=($_POST['category_code']??'')===$item['code']?'selected':''?>><?=esc($item['label'])?></option><?php endforeach ?></select></label><label class="wide">Nombre del negocio<input id="registration-search" type="search" autocomplete="off" placeholder="Escribe al menos dos letras" disabled><small>Buscamos en los negocios publicados y también en los registros internos que aún no son visibles.</small></label></div><div id="registration-results" class="business-registration-results" aria-live="polite"><p>Selecciona destino y categoría para iniciar la búsqueda.</p></div><button type="button" class="pill light" id="registration-not-found" disabled>Mi negocio no aparece</button><input type="hidden" name="application_type" id="registration-application-type" value=""><input type="hidden" name="business_id" id="registration-business-id" value=""><label class="wide" id="registration-new-name-wrap" hidden>Nombre legal o comercial del negocio que falta<input name="business_name" id="registration-new-name" maxlength="180" autocomplete="organization"><small>El registro quedará como solicitud privada. El equipo comprobará que el negocio existe antes de crear su ficha.</small></label></fieldset><fieldset><legend>2. Cuéntanos quién eres</legend><div class="destination-form-grid"><label>Tu nombre<input name="display_name" maxlength="180" autocomplete="name" required value="<?=esc($_POST['display_name']??'')?>"></label><label>Correo de contacto<input type="email" name="email" maxlength="254" autocomplete="email" required value="<?=esc($_POST['email']??'')?>"></label><label>Teléfono (opcional)<input type="tel" name="phone" maxlength="40" autocomplete="tel" value="<?=esc($_POST['phone']??'')?>"></label><label>Tu relación con el negocio<select name="relationship_code" required><option value="">Selecciona</option><option value="owner">Soy propietario/a</option><option value="authorized_representative">Soy representante autorizado/a</option></select></label><label class="wide">Información para revisar la solicitud<textarea name="message" rows="3" maxlength="1000" placeholder="Cuéntanos cómo podemos comprobar que representas este negocio"><?=esc($_POST['message']??'')?></textarea></label></div></fieldset><fieldset><legend>3. Crea tu acceso</legend><div class="destination-form-grid"><label>Contraseña<input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password" required><small>Al menos 12 caracteres, con letras y números.</small></label><label>Confirma la contraseña<input type="password" name="password_confirm" minlength="12" maxlength="200" autocomplete="new-password" required></label></div></fieldset><label class="admin-checkbox-field account-consent"><span>Autorizo el uso de mis datos para revisar y responder esta solicitud. Leí la <a href="/v1/privacidad/" target="_blank" rel="noopener">política de tratamiento de datos</a>.</span><input type="checkbox" name="consent" value="1" required></label><button class="pill" type="submit" id="registration-submit" disabled>Crear cuenta y enviar a revisión</button></form><p>¿Ya tienes cuenta? <a href="/v1/negocios/acceso/">Inicia sesión</a></p><div class="account-social-options"><strong>Acceso con otros proveedores</strong><p>Google y Microsoft se habilitarán cuando estén configurados. Por ahora, crea la cuenta con correo y contraseña.</p></div></section></main><script src="/v1/assets/business-registration.js?v=3" defer></script></body></html>
